diff --git a/mailnews/imap/src/nsImapMailFolder.cpp b/mailnews/imap/src/nsImapMailFolder.cpp
index 5784d74eca7..14012cd189a 100644
--- a/mailnews/imap/src/nsImapMailFolder.cpp
+++ b/mailnews/imap/src/nsImapMailFolder.cpp
@@ -1304,16 +1304,28 @@ NS_IMETHODIMP nsImapMailFolder::Compact(nsIUrlListener* aListener,
 NS_IMETHODIMP nsImapMailFolder::MarkPendingRemoval(nsIMsgDBHdr* aHdr,
                                                    bool aMark) {
   NS_ENSURE_ARG_POINTER(aHdr);
+  // Only touch expungedBytes when the flag actually changes state. This method
+  // gets called repeatedly for the same headers (e.g. from
+  // ApplyRetentionSettings every time it runs), so unconditionally adjusting
+  // the count would let it drift far above the real reclaimable size.
+  nsAutoCString pendingRemoval;
+  aHdr->GetStringProperty("pendingRemoval", pendingRemoval);
+  bool wasMarked = !pendingRemoval.IsEmpty();
+  if (aMark == wasMarked) {
+    return NS_OK;
+  }
+
+  aHdr->SetStringProperty("pendingRemoval", aMark ? "1"_ns : ""_ns);
+
   uint32_t offlineMessageSize;
   aHdr->GetOfflineMessageSize(&offlineMessageSize);
-  aHdr->SetStringProperty("pendingRemoval", aMark ? "1"_ns : ""_ns);
-  if (!aMark) return NS_OK;
   nsresult rv = GetDatabase();
   NS_ENSURE_SUCCESS(rv, rv);
   nsCOMPtr<nsIDBFolderInfo> dbFolderInfo;
   rv = mDatabase->GetDBFolderInfo(getter_AddRefs(dbFolderInfo));
   NS_ENSURE_SUCCESS(rv, rv);
-  return dbFolderInfo->ChangeExpungedBytes(offlineMessageSize);
+  return dbFolderInfo->ChangeExpungedBytes(
+      aMark ? (int32_t)offlineMessageSize : -(int32_t)offlineMessageSize);
 }

 NS_IMETHODIMP nsImapMailFolder::Expunge(nsIUrlListener* aListener,
diff --git a/mailnews/imap/test/unit/test_autosync_date_constraints.js b/mailnews/imap/test/unit/test_autosync_date_constraints.js
index 382a4d0e93d..909a8283877 100644
--- a/mailnews/imap/test/unit/test_autosync_date_constraints.js
+++ b/mailnews/imap/test/unit/test_autosync_date_constraints.js
@@ -83,6 +83,58 @@ add_task(function test_applyRetentionSettings() {
   }
 });

+// Regression test for bug 2054592. markPendingRemoval() gets called repeatedly
+// for the same headers (e.g. ApplyRetentionSettings re-marks every expired
+// offline message on each run). expungedBytes must reflect the state change,
+// not accumulate on every call.
+add_task(function test_markPendingRemovalAccounting() {
+  const folder = IMAPPump.inbox;
+  const header = [...folder.msgDatabase.enumerateMessages()][0];
+  Assert.ok(
+    header.flags & Ci.nsMsgMessageFlags.Offline,
+    "test message should be stored offline"
+  );
+  const size = header.offlineMessageSize;
+  Assert.greater(size, 0, "offline message should have a non-zero size");
+
+  const initial = folder.expungedBytes;
+
+  // First mark: expungedBytes grows by the message's offline size.
+  folder.markPendingRemoval(header, true);
+  Assert.equal(header.getStringProperty("pendingRemoval"), "1");
+  Assert.equal(
+    folder.expungedBytes,
+    initial + size,
+    "marking should add the message size once"
+  );
+
+  // Re-marking an already-marked message must be a no-op for expungedBytes.
+  folder.markPendingRemoval(header, true);
+  folder.markPendingRemoval(header, true);
+  Assert.equal(
+    folder.expungedBytes,
+    initial + size,
+    "re-marking must not inflate expungedBytes"
+  );
+
+  // Unmarking removes the message size again.
+  folder.markPendingRemoval(header, false);
+  Assert.equal(header.getStringProperty("pendingRemoval"), "");
+  Assert.equal(
+    folder.expungedBytes,
+    initial,
+    "unmarking should subtract the message size"
+  );
+
+  // Redundant unmark is likewise a no-op.
+  folder.markPendingRemoval(header, false);
+  Assert.equal(
+    folder.expungedBytes,
+    initial,
+    "redundant unmark should not change expungedBytes"
+  );
+});
+
 add_task(function endTest() {
   teardownIMAPPump();
 });
